const {o,P,bounds}=ctx; const n=[]; const bw=o.matW, bh=o.matH;
for(let x=Math.floor(bounds.x0/bw)*bw; x<bounds.x1; x+=bw){
  for(let y=Math.floor(bounds.y0/bh)*bh; y<bounds.y1; y+=bh){
    n.push({tag:'rect',attrs:{x:P.X(x),y:P.Y(y),width:P.S(bw),height:P.S(bh),fill:'none',stroke:'#6b5f3a','stroke-width':2,opacity:0.55}});
  }
}
return n;

const {o,P,bounds,shade}=ctx;
const cx=(bounds.x0+bounds.x1)/2, cy=(bounds.y0+bounds.y1)/2;
const maxR=Math.max(bounds.x1-bounds.x0,bounds.y1-bounds.y0)/2;
const n=[];
for(let i=1;i<=o.rings;i++){
  n.push({tag:'circle',attrs:{cx:P.X(cx),cy:P.Y(cy),r:P.S(maxR*i/o.rings),fill:'none',stroke:shade(o.color,-0.3),'stroke-width':1,opacity:0.4}});
}
return n;
